"use client"

import * as React from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { ChevronDown, MoreHorizontal, Search, Download, Trash2, Send } from "lucide-react"
import { toast } from "sonner"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"

const BOOKINGS = [
  {
    id: "B-1234",
    user: "John Doe",
    destination: "New York (JFK)",
    date: "2024-06-15",
    amount: "$450.00",
    status: "Confirmed",
  },
  {
    id: "H-5678",
    user: "Sarah Smith",
    destination: "London (LHR)",
    date: "2024-07-01",
    amount: "$1,200.00",
    status: "Pending",
  },
  {
    id: "B-9012",
    user: "Mike Johnson",
    destination: "Tokyo (NRT)",
    date: "2024-08-10",
    amount: "$850.00",
    status: "Confirmed",
  },
  {
    id: "H-3456",
    user: "Emily Davis",
    destination: "Paris (CDG)",
    date: "2024-09-05",
    amount: "$920.00",
    status: "Cancelled",
  },
  {
    id: "B-7890",
    user: "David Wilson",
    destination: "Dubai (DXB)",
    date: "2024-10-20",
    amount: "$600.00",
    status: "Confirmed",
  },
]

export default function BookingsPage() {
  const [selectedBookings, setSelectedBookings] = React.useState<string[]>([])
  const [isAlertOpen, setIsAlertOpen] = React.useState(false)
  const [actionType, setActionType] = React.useState<string | null>(null)

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedBookings(BOOKINGS.map((b) => b.id))
    } else {
      setSelectedBookings([])
    }
  }

  const handleSelectBooking = (id: string, checked: boolean) => {
    if (checked) {
      setSelectedBookings((prev) => [...prev, id])
    } else {
      setSelectedBookings((prev) => prev.filter((item) => item !== id))
    }
  }

  const handleBulkAction = (action: string) => {
    setActionType(action)
    setIsAlertOpen(true)
  }

  const executeAction = () => {
    // Mock action execution
    const count = selectedBookings.length
    let message = ""
    if (actionType === "resend") message = `${count} bookings processed: Tickets resent successfully`
    if (actionType === "cancel") message = `${count} bookings processed: Cancellation requests submitted`
    if (actionType === "export") message = `${count} bookings exported to CSV`

    toast.success("Bulk Operation Successful", {
      description: message,
    })
    setSelectedBookings([])
    setIsAlertOpen(false)
    setActionType(null)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">All Bookings</h1>
          <p className="text-muted-foreground">Manage and track all travel reservations.</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="relative w-64">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input placeholder="Search bookings..." className="pl-8" />
              </div>
            </div>

            {selectedBookings.length > 0 && (
              <div className="flex items-center gap-2">
                <span className="text-sm text-muted-foreground">{selectedBookings.length} selected</span>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="outline">
                      Bulk Actions <ChevronDown className="ml-2 h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuLabel>Actions</DropdownMenuLabel>
                    <DropdownMenuItem onClick={() => handleBulkAction("resend")}>
                      <Send className="mr-2 h-4 w-4" /> Resend Tickets
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => handleBulkAction("export")}>
                      <Download className="mr-2 h-4 w-4" /> Export CSV
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={() => handleBulkAction("cancel")} className="text-destructive">
                      <Trash2 className="mr-2 h-4 w-4" /> Cancel Booking
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>
            )}
          </div>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[50px]">
                  <Checkbox
                    checked={selectedBookings.length === BOOKINGS.length && BOOKINGS.length > 0}
                    onCheckedChange={(checked) => handleSelectAll(checked as boolean)}
                  />
                </TableHead>
                <TableHead>Booking ID</TableHead>
                <TableHead>User</TableHead>
                <TableHead>Destination</TableHead>
                <TableHead>Date</TableHead>
                <TableHead>Amount</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {BOOKINGS.map((booking) => (
                <TableRow key={booking.id} data-state={selectedBookings.includes(booking.id) ? "selected" : undefined}>
                  <TableCell>
                    <Checkbox
                      checked={selectedBookings.includes(booking.id)}
                      onCheckedChange={(checked) => handleSelectBooking(booking.id, checked as boolean)}
                    />
                  </TableCell>
                  <TableCell className="font-medium">{booking.id}</TableCell>
                  <TableCell>{booking.user}</TableCell>
                  <TableCell>{booking.destination}</TableCell>
                  <TableCell>{booking.date}</TableCell>
                  <TableCell>{booking.amount}</TableCell>
                  <TableCell>
                    <Badge
                      variant={
                        booking.status === "Confirmed"
                          ? "default"
                          : booking.status === "Pending"
                            ? "secondary"
                            : "destructive"
                      }
                    >
                      {booking.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-right">
                    <Button variant="ghost" size="icon">
                      <MoreHorizontal className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <AlertDialog open={isAlertOpen} onOpenChange={setIsAlertOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action will be applied to {selectedBookings.length} selected bookings.
              {actionType === "cancel" && " This process cannot be undone."}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={executeAction}
              className={actionType === "cancel" ? "bg-destructive hover:bg-destructive/90" : ""}
            >
              Continue
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
